/**
 * Regenerate src/onchain/abi.ts from the Foundry build output so viem gets fully typed
 * contract ABIs. Run after `pnpm contracts:build`: `pnpm contracts:abi`.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const contracts = {
  A2ASettlement: "a2aSettlementAbi",
  TestUSDC: "testUsdcAbi",
  ReputationRegistry: "reputationRegistryAbi",
  IdentityRegistry: "identityRegistryAbi",
} as const;

let out =
  "// GENERATED by src/scripts/sync-abi.ts from contracts/out — do not edit by hand.\n" +
  "// Regenerate with: pnpm contracts:build && pnpm contracts:abi\n\n";

for (const [name, exportName] of Object.entries(contracts)) {
  const artifact = JSON.parse(
    readFileSync(join(root, "contracts", "out", `${name}.sol`, `${name}.json`), "utf8"),
  ) as { abi: unknown; bytecode: { object: string } };
  out += `export const ${exportName} = ${JSON.stringify(artifact.abi, null, 2)} as const;\n\n`;
  const bytecodeName = exportName.replace(/Abi$/, "Bytecode");
  out += `export const ${bytecodeName} = "${artifact.bytecode.object}" as const;\n\n`;
}

writeFileSync(join(root, "src", "onchain", "abi.ts"), out);
console.log(`Wrote src/onchain/abi.ts (${Object.values(contracts).join(", ")})`);
